```js
// giftcards/redeem.js
async function redeem(cardId, amount) {
  const { Item: card } = await ddb.get({ TableName: 'GiftCards', Key: { cardId } });
  if (!card || card.balance < amount) throw new Error('insufficient_balance');
  card.balance -= amount;
  card.lastRedeemedAt = Date.now();
  await ddb.put({ TableName: 'GiftCards', Item: card });
  return card.balance;
}

// routes/checkout.js
router.post('/checkout/giftcard', async (req, res) => {
  const remaining = await redeem(req.body.cardId, req.body.amount);
  res.json({ remaining });
});
```

