Hi, this is a review of PR #482 "Account tidy-ups" from a new hire on our TS backend. Description from the PR: "Adds `touchLastLogin` for the session refresh and `mergeAccounts` for the support tool's duplicate-account merge. Used the db client directly since I couldn't find examples." For context, our data access normally goes through `AccountRepo` (src/repos/accountRepo.ts) and it exposes `withTransaction(fn)`, which `AccountRepo.closeAccount` uses. Nobody else calls `dynamo` directly outside the repo folder.

```ts
// src/services/accountMaintenance.ts
import { dynamo } from '../clients/dynamo';

export async function touchLastLogin(accountId: string) {
  await dynamo.update({
    TableName: 'Accounts',
    Key: { accountId },
    UpdateExpression: 'SET lastLoginAt = :now',
    ExpressionAttributeValues: { ':now': Date.now() },
  });
}

export async function mergeAccounts(keepId: string, dropId: string) {
  const drop = await dynamo.get({ TableName: 'Accounts', Key: { accountId: dropId } });
  await dynamo.update({
    TableName: 'Accounts',
    Key: { accountId: keepId },
    UpdateExpression: 'ADD loyaltyPoints :p',
    ExpressionAttributeValues: { ':p': drop.Item.loyaltyPoints },
  });
  await dynamo.update({
    TableName: 'Accounts',
    Key: { accountId: dropId },
    UpdateExpression: 'SET #s = :closed, loyaltyPoints = :zero',
    ExpressionAttributeNames: { '#s': 'status' },
    ExpressionAttributeValues: { ':closed': 'MERGED', ':zero': 0 },
  });
}
```

